<script lang="ts">import type {NightWindow} from '../generated/NightWindow';import {colors} from '../charts';let {nights,bedWindow=null,wakeWindow=null}:{nights:NightWindow[],bedWindow?:[number,number]|null,wakeWindow?:[number,number]|null}=$props();const y=(hour:number)=>8+((hour<12?hour+24:hour)-21.5)/10*102;</script><svg viewBox="0 0 326 128" class="plot" aria-label="Bed and wake times over two weeks">{#if bedWindow}<rect x="40" y={y(bedWindow[0])} width="286" height={y(bedWindow[1])-y(bedWindow[0])} rx="3" fill={colors.violet} opacity=".12"/>{/if}{#if wakeWindow}<rect x="40" y={y(wakeWindow[0])} width="286" height={y(wakeWindow[1])-y(wakeWindow[0])} rx="3" fill={colors.violet} opacity=".12"/>{/if}{#each [['22:00',22],['02:00',2],['06:00',6]] as tick}<text x="0" y={y(Number(tick[1]))+4} fill="#69728A" font-size="11">{tick[0]}</text><line x1="40" x2="326" y1={y(Number(tick[1]))} y2={y(Number(tick[1]))} stroke="rgba(255,255,255,.05)"/>{/each}{#each nights as n,i}<rect x={40+i*286/Math.max(nights.length,1)} y={y(n.bedHour)} width={Math.min(14,280/Math.max(nights.length,1)-3)} height={Math.max(1,y(n.wakeHour)-y(n.bedHour))} rx="7" fill={i===nights.length-1?colors.violet:'rgba(155,140,255,.38)'}/>{/each}<text x="40" y="126" fill="#69728A" font-size="11">2 weeks ago</text><text x="326" y="126" text-anchor="end" fill="#69728A" font-size="11">Last night</text></svg><style>.plot{display:block;width:100%}</style>